mapper.select:
select A.FINPROD_ID code, IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) shortName, A.FINPROD_NAME "name" from FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
A.P_FINPROD_ID IS NULL AND B.ISSUE_STATUS = #{ISSUE_STATUS01}
and (instr(A.FINPROD_ID, #{param}) > 0 or instr(A.FINPROD_NAME, #{param}) > 0 or instr(A.FINPROD_ABBR, #{param}) > 0)

select FP.FINPROD_ID id, concat_ws('',FP.FINPROD_MARKET_ID ,':', FP.FINPROD_ABBR) text
from FIN_PRODUCT FP, FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO_AUTHORITY PPA
where FP.FINPROD_ID = FPA.FINPROD_ID
and FP.FINPROD_TYPE2 = #{finprodTypeProd}
and FP.P_FINPROD_ID IS NULL

	and FPA.ISSUE_STATUS = #{issueStatus}


and FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID


	and (FP.FINPROD_MARKET_ID like concat('%',#{search},'%')
	or FP.FINPROD_ABBR like concat('%',#{search},'%'))


	and PPA.USER_ID = #{userId}



		and FP.FINPROD_ID = #{initValue}

select FEE_ID id, concat_ws('',FEE_ID ,':', FEE_NAME) text from MST_FEEINFO where APPLY_TYPE = #{relationProd}
and (FEE_ID like concat('%', #{search}, '%') or FEE_NAME like concat('%', #{search}, '%'))
and FEE_ID IN (#{initValue})
